#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum KmdfObjectKind {
    Driver,
    DeviceInit,
    Device,
    Queue,
    Request,
    WaitLock,
    IoTarget,
    FileObject,
    Memory,
    String,
    SpinLock,
    Timer,
    WorkItem,
}

impl KmdfObjectKind {
    /// Per-kind context layout: the default context bytes allocated when the
    /// caller asks for none, and the alignment of the context block.
    const fn layout(self) -> (usize, usize) {
        match self {
            Self::Driver => (0x20, 8),
            Self::DeviceInit => (0x40, 8),
            Self::Device => (0x80, 16),
            Self::Queue => (0x80, 16),
            Self::Request => (0x80, 8),
            Self::WaitLock => (0x20, 8),
            Self::IoTarget => (0x80, 8),
            Self::FileObject => (0x40, 8),
            Self::Memory => (0x40, 8),
            Self::String => (0x20, 8),
            Self::SpinLock => (0x20, 8),
            Self::Timer => (0x40, 8),
            Self::WorkItem => (0x40, 8),
        }
    }
}

